response:
Um ein benutzerdefiniertes WordPress-Plugin zu entwickeln, das einer bestehenden Website bestimmte Funktionen hinzufügt, benötigen wir einige weiterführende Details:

1. Bezeichnung des Plugins: "Custom Functions Plugin" (CFP)

2. Bezeichnung des benutzerdefinierten Beitragstyps: "Produkt"

3. Bezeichnung des Widgets: "Produkt-Widget"

4. Liste der Shortcodes:

   - [product-list]: Zeigt eine Liste von Produkten an.
   - [product-details]: Zeigt Details zu einem bestimmten Produkt an.
   - [product-filter]: Filtere Produkte nach Kategorie, Preisspanne usw.

Jetzt können wir die Schritte zur Erstellung des Plugins in WordPress beschreiben:

1. Erstellen eines neuen Plugins-Ordners mit dem Namen "custom-functions-plugin" in der "wp-content/plugins" -Unterlage von WordPress.

2. Erstellen des Haupt-Plugins-Dateisystems, worin wir alle Plugin-Komponenten enthalten werden:

   - custom-functions-plugin.php
   - custom-post-types.php
   - widgets.php
   - shortcodes.php

3. Öffnen von "custom-functions-plugin.php" und fügen Sie das erste Block des Plugins hinzu:

```php
<?php
/*
Plugin Name: Custom Functions Plugin
Plugin URI: https://example.com/custom-functions-plugin/
Description: Custom functions, post types, widgets and shortcodes plugin.
Version: 1.0
Author: Your Name
Author URI: https://example.com/
License: GPL2
Text Domain: cfp
Domain Path: /languages
*/
```

Jetzt haben wir einige grundlegende Informationen eingefügt, die für das Plugin erforderlich sind.

4. In den Dateien "custom-post-types.php", "widgets.php" und "shortcodes.php" fügen Sie je nach Ihrer Aufgabenliste die folgenden Kodeteile hinzu:

a. "custom-post-types.php":

```php
<?php
/**
 * Custom Post Types.
 *
 * @package Custom_Functions_Plugin
 */

// Register Produkt-Post-Typ
function cfp_register_product_post_type() {
    $args = array(
        'labels' => array(
            'name'          => __( 'Produkte', 'cfp' ),
            'singular_name' => __( 'Produkt', 'cfp' ),
            'add_new_item'  => __( 'Neues Produkt hinzufügen', 'cfp' ),
            'edit_item'     => __( 'Bearbeiten', 'cfp' ),
        ),
        'description'       => __( 'Hauptproduktkategorien.', 'cfp' ),
        'public'             => true,
        'menu_icon'          => 'dashicons-cart',
        'show_in_rest'       => true,
        'supports'           => array( 'title', 'editor', 'thumbnail' ),
        'menu_position'      => 20,
        'has_archive'         => true,
        'taxonomies'          => array( 'product_cat' ),
        'rewrite'             => array( 'slug' => 'products' ),
    );

    register_post_type( 'product', $args );
}

// Aktivieren des Post-Typs
function cfp_product_post_type() {
    add_action( 'init', 'cfp_register_product_post_type' );
}
add_action( 'init', 'cfp_product_post_type' );
```

b. "widgets.php":

```php
<?php
/**
 * Widgets.
 *
 * @package Custom_Functions_Plugin
 */

// Register Produkt-Widget
function cfp_register_product_widget() {
    register_widget( 'CFP_Product_Widget' );
}

class CFP_Product_Widget extends WP_Widget {

    function __construct() {
        parent::__construct(
            'cfp_product_widget',
            __( 'Produkt-Widget', 'cfp' ),
            array( 'description' => __( 'Zeigt eine Liste von Produkten an.', 'cfp' ) )
        );
    }

    function widget( $args, $instance ) {
        // Widget Code hier einfügen
    }
}

add_action( 'widgets_init', 'cfp_register_product_widget' );
```

c. "shortcodes.php":

```php
<?php
/**
 * Shortcodes.
 *
 * @package Custom_Functions_Plugin
 */

function cfp_product_list( $atts ) {
    extract( shortcode_atts( array(
        'posts_per_page' => 5,
    ), $atts ) );

    $args = array(
        'post_type'      => 'product',
        'posts_per_page' => $posts_per_page,
        'orderby'        => 'date',
        'order'          => 'DESC',
    );

    ob_start();

    // Shortcode Code hier einfügen

    return ob_get_clean();
}
add_shortcode( 'product-list', 'cfp_product_list' );

function cfp_product_details( $atts ) {
    extract( shortcode_atts( array(
        'product_id' => 0,
    ), $atts ) );

    if ( ! $product_id ) {
        return '';
    }

    $product = get_post( $product_id );

    ob_start();

    // Shortcode Code hier einfügen

    return ob_get_clean();
}
add_shortcode( 'product-details', 'cfp_product_details' );

function cfp_product_filter( $atts ) {
    extract( shortcode_atts( array(), $atts ) );

    // Shortcode Code hier einfügen

    return '';
}
add_shortcode( 'product-filter', 'cfp_product_filter' );
```

5. Jetzt fügen Sie das Custom-Design für Ihre Website hinzu, um ein konsistentes Design für Ihre Shortcodes, Widgets und Post-Typen zu erzielen. Sie können dies entweder in der Theme-Datei (`functions.php`) oder einer separaten Style-Datei (`custom-functions-plugin.css`) umsetzen.

6. Veröffentlichen Sie das Plugin in WordPress, indem Sie das Plugin-Ordner in die "wp-content/plugins" -Unterlage ihres WordPress-Verzeichnisses kopieren, das Plugin aktivieren und den "Custom Functions Plugin" neu installieren.

7. Zum Dokumentieren des Plugins, fügen Sie eine Readme-Datei hinzu (README.md) im Root des Plugins-Ordners, in der eine detaillierte Beschreibung und Anleitung für die Installation, Anwendung und Wartung des Plugins enthalten ist.

8. Veröffentlichen Sie das Plugin auf einem beliebigen WordPress-Plugin-Dienst, wie z.B. WordPress.org, um es anderen WordPress-Nutzern zur Verfügung zu stellen.

Mit diesen Schritten können Sie ein benutzerdefiniertes WordPress-Plugin erstellen, das einer bestehenden Website spezifische Funktionen hinzufügt. Beachten Sie, dass die weiterführenden Details auf Ihre Website und Ihre Anforderungen abgestimmt werden sollten. Das Design und die Ästhetik des Plugins sollten stets mit der bestehenden Website des Kunden übereinstimmen und es sollte mit der neuesten Version von WordPress kompatibel sein. Verwenden Sie Dokumentation und Updates sorgfältig, um das Plugin für die zukünftige Wartung und Weiterentwicklung vorzubereiten.

Hier ein Überblick auf das Entwickeln eines benutzerdefinierten WordPress-Plugin mit den vorgeschlagenen Funktionen:

### 1. Plugin-Namensgebung und Schematisierung

Beim Entwickeln eines eigenen WordPress-Plugins, ist es wichtig, entscheidende Entscheidungen zu treffen, wie diese sein sollen. Zu Beginn sollten Sie einen einzigartigen Namen und eine platzsparende Bezeichnung für das Plugin aussuchen, etwa "Custom Features Extension" oder "Enhanced Content Types Suite". Anschließend erstellen Sie das Plugin-Verzeichnis mit der gleichen Bezeichnung, das unter dem Ordner „wp-content/plugins“ im Verzeichnis von WordPress abgelegt werden sollte.

### 2. Benutzerdefinierten Beitragstyp

Um den benutzerdefinierten Beitragstyp erstellen zu können, folgen wir diesen Schritten:

- Erstellen Sie das Abhängigkeits- und Installations-Script (zip, ein einfaches PHP-Skript) und installieren Sie die notwendigen Abhängigkeiten, wie z.B.:

```
require_once( ABSPATH . 'wp-admin/includes/upgrade.php' );
require_once( ABSPATH . 'wp-admin/includes/schema.php' );
require_once( ABSPATH . 'wp-admin/includes/class-wp-upgrader.php' );
```

- Fügen Sie die Tabelle für den benutzerdefinierten Beitragstyp in das Plugin-Verzeichnis hinzu, wie folgt:

```php
// Define custom post type’s name
$custom_post_type_name = 'custom_post_type';

// Define custom post type's labels
$labels = array(
    'name'              => _x( $custom_post_type_name . 's', 'Post Type General Name' ),
    'singular_name'    => _x( $custom_post_type_name, 'Post Type Singular Name' ),
    'menu_name'         => __( $custom_post_type_name . 's', 'textdomain' ),
    'all_items'         => __( 'All ' . $custom_post_type_name . 's', 'textdomain' ),
    'edit_item'         => __( 'Edit ' . $custom_post_type_name, 'textdomain' ),
    'update_item'       => __( 'Update ' . $custom_post_type_name, 'textdomain' ),
    'search_items'      => __( 'Search ' . $custom_post_type_name, 'textdomain' ),
    'not_found'          => __( 'Not found', 'textdomain' ),
    'not_found_in_trash' => __( 'Not found in Trash', 'textdomain' ),
);

// Add custom post type to WordPress
function register_custom_post_type() {

    // Set arguments for custom post type
    $args = array(
        'label'               => $labels['menu_name'],
        'description'         => '',
        'public'              => true,
        'menu_icon'           => 'dashicons-welcome-write-blog',
        'supports'            => array( 'title', 'editor', 'thumbnail' ),
        'taxonomies'          => array( 'category', 'post_tag' ),
        'show_in_rest'        => true,
        'menu_position'       => 5,
        'has_archive'          => true,
        'labels'              => $labels,
        'rewrite'             => array( 'slug' => $custom_post_type_name ),
    );

    // Register custom post type
    register_post_type( $custom_post_type_name, $args );

}
add_action( 'init', 'register_custom_post_type' );

// Create custom post type taxonomy
function custom_taxonomy() {

    $labels = array(
        'name'              => _x( 'Custom Taxonomies', 'Taxonomy General Name' ),
        'singular_name'    => _x( 'Custom Taxonomy', 'Taxonomy Singular Name' ),
        'search_items'     => __( 'Search Custom Taxonomies' ),
        'all_items'        => __( 'All Custom Taxonomies' ),
        'edit_item'        => __( 'Edit Custom Taxonomy' ),
        'update_item'      => __( 'Update Custom Taxonomy' ),
        'add_new_item'     => __( 'Add New Custom Taxonomy' ),
        'menu_name'        => __( 'Custom Taxonomies', 'textdomain' ),
    );

    $args = array(
        'labels'            => $labels,
        'hierarchical'      => true,
        'public'             => true,
        'args'               => array( 'hide_empty' => false ),
        'show_admin_column' => true,
        'show_ui'             => true,
        'query_var'           => true,
        'rewrite'            => array( 'slug' => 'custom_taxonomy' ),
    );

    register_taxonomy( $custom_post_type_name, array( $custom_post_type_name ), $args );

}
add_action( 'init', 'custom_taxonomy' );
```

- Um die benutzerdefinierte Postartikel auf der Website sichtbar zu machen, fügen Sie den Beitragstyp zu den Optionen hinzu:

```php
// Add custom post type to the ‘Post type’ dropdown menu
function add_custom_post_type_to_dropdown() {
    register_taxonomy_for_object_type( 'category', $custom_post_type_name );
    register_taxonomy_for_object_type( 'post_tag', $custom_post_type_name );
}
add_action( 'init', 'add_custom_post_type_to_dropdown' );
```

### 3. Neues Widget

Um ein neues Widget zu erstellen, folgen Sie diesen Schritten:

- Erstellen Sie eine Funktion zum Registrieren des Widgets:

```php
// Register custom widget
function register_custom_widget() {
  register_widget( 'Custom_Widget' );
}
add_action( 'widgets_init', 'register_custom_widget' );
```

- Erstellen Sie eine Widget-Klasse mit den gewünschten Eigenschaften, z.B.:

```php
// Custom Widget Class
class Custom_Widget extends WP_Widget {

    function __construct() {
        parent::__construct(
            'custom_widget',
            __( 'Custom Widget', 'textdomain' ),
            array( 'description' => __( 'Custom Widget for custom functionality', 'textdomain' ) )
        );
    }

    function widget( $args, $instance ) {
        // Widget code here
    }

}

// Register custom widget
function register_custom_widget() {
  register_widget( 'Custom_Widget' );
}
add_action( 'widgets_init', 'register_custom_widget' );
```

### 4. Zusätzliche Shortcodes

Zusätzlich zu den obigen Funktionen, können Sie die folgenden Shortcodes implementieren:

- Erstellen Sie eine Funktion zum Registrieren der Shortcodes:

```php
// Register shortcodes
function register_custom_shortcodes() {
    add_shortcode( 'custom_shortcode', 'custom_shortcode_callback' );
    add_shortcode( 'other_shortcode', 'other_shortcode_callback' );
}
add_action( 'init', 'register_custom_shortcodes' );
```

- Schreiben Sie Funktionen für die Shortcodes:

```php
// Callback function for custom shortcode
function custom_shortcode_callback( $atts ) {
    // Shortcode code here
    return $shortcode_output;
}

// Callback function for other shortcode
function other_shortcode_callback( $atts ) {
    // Shortcode code here
    return $other_shortcode_output;
}
```

### 5. Konformität mit aktuellem Design und Ästhetik

Zum Einhalten der Ästhetik und des Designs der Website, können Sie die folgenden Schritte und Anpassungen durchführen:

- Schreiben Sie einen CSS-Datei-, der die benutzerdefinierten Widget und Shortcodes-Stile festlegt, z.B.:

```css
.custom-widget-class {
    /* Custom widget styles */
}

.custom-shortcode {
    /* Custom shortcode styles */
}
```

- Laden Sie den CSS-Code in das Plugin ein, und fügen Sie ihn am Ende des `functions.php`-Datei hinzu:

```php
// Add custom plugin styles
function custom_plugin_styles() {
    wp_register_style( 'custom-plugin-style', plugin_dir_url( __FILE__ ) . 'css/custom-plugin-style.css' );
    wp_enqueue_style( 'custom-plugin-style' );
}
add_action( 'wp_enqueue_scripts', 'custom_plugin_styles' );
```

- Ändern Sie die Farben, Schriftarten und andere Design-Elemente der Benutzerdefinierungen, um sie mit der aktuellen Website-Konfiguration zu kombinieren.

### 6. Dokumentation für Wartungsarbeiten und Updates

Um das Plugin vollständig zu dokumentieren, verwenden Sie das Wiki zur Dokumentation von WordPress. Verfassen Sie eine Dokumentation, die das Plugin, seine Features, Konfiguration, Registrierung, Installation, Anpassungen und Fehlerbehebungen beinhaltet.

Dieses Plugin-Entwicklungsbeispiel kann Ihnen als Grundlage dienen. Es liegt an Ihnen, es zu erweitern und weiterzuentwickeln, um genaue Funktionen hinzuzufügen und den Code zu optimieren. Verwenden Sie zudem bestehende WordPress-Entwicklungsressourcen zur weiteren Verbesserung Ihres Plugins.

Um ein benutzerdefiniertes WordPress-Plugin zu entwickeln, das einer bestehenden Website bestimmte Funktionen hinzufügt, folgen Sie bitte den nachfolgenden Schritten:

1. Planung und Konzeption: Identifizieren Sie die benötigten Funktionen und verarbeiten Sie ihre priorisierten Bedürfnisse. Legen Sie die Benutzererwartungen und -anforderungen fest. Bestimmen Sie die konsistenten Design- und Stilkonzepte, die mit Ihrem bestehendem Branding und der Ästhetik der Website übereinstimmen.

2. Installieren von WordPress Developer Tools: Installieren Sie die empfohlenen Tools für die Entwicklerarbeit, wie zum Beispiel:

- Underscore.js: Ein JavaScript-Utility-Bibliothek.
- jQuery: Eine interaktive JavaScript-Bibliothek für das Web.
- WP Cli: Ein Befehlszeilenwerkzeug, um mit Ihrem WordPress-Installation zu interagieren.
- WP Edit: Eine browserbasierte IDE zur Entwicklung von WordPress-Codes.

3. Anlegen des Plugins: Erstellen Sie ein neues WordPress-Plugin-Folder mit dem Namen, den Sie für das Plugin festgelegt haben, und legen Sie die Dateien hin:

- `plugin-name.php`: Das Hauptdatei- und Eintragungsdatei.
- `css`: Enthält alle CSS-Dateien, die von dem Plugin benötigt werden.
- `js`: Enthält alle JavaScript-Dateien, die von dem Plugin benötigt werden.
- `src`: Optionaler Ordner, um Ihre vollständige Codebasis zu organisieren.

4. Instanziieren Sie das Plugin:

```php
<?php
/**
 * Plugin Name: Plugin Name
 * Version: 1.0.0
 * Author: Author's Name
 * Description: A custom WordPress plugin with features.
 * Text Domain: plugin-name
 * Domain Path: /languages
 */

// Include your required PHP files
require_once __DIR__ . '/src/init.php';
require_once __DIR__ . '/src/custom-post-type.php';
require_once __DIR__ . '/src/custom-widget.php';
require_once __DIR__ . '/src/shortcodes.php';

// Deactivate and delete previous versions of the plugin
function plugin_name_uninstall() {
  // Your code here
}
register_uninstall_hook( __FILE__, 'plugin_name_uninstall' );
```

5. Implementieren Sie die benötigten Funktionen:

### Benutzerdefinierter Beitragstyp:
Im ordner `src` erstellen Sie die Datei `custom-post-type.php` und Fügen Sie Folgendes hinzu:

```php
<?php
/**
 * Register Custom Post Type
 */
function plugin_name_custom_post_type() {

  $labels = array(
    'name'                  => _x( 'Custom Post Type', 'Post Type General Name' ),
    'singular_name'         => _x( 'Custom Post', 'Post Type Singular Name' ),
    'search_items'          => __( 'Search Custom Posts' ),
    'all_items'             => __( 'All Custom Posts' ),
    'edit_item'             => __( 'Edit Custom Post' ),
    'update_item'           => __( 'Update Custom Post' ),
    'add_new_item'          => __( 'Add New Custom Post' ),
    'menu_name'             => __( 'Custom Posts' ),
  );
  $args = array(
    'label'                 => __( 'custom-post-type' ),
    'description'           => __( 'Custom Post Type' ),
    'labels'                => $labels,
    'public'                => true,
    'menu_icon'             => 'dashicons-welcome-write-blog',
    'supports'              => array( 'title', 'editor', 'thumbnail' ),
    'has_archive'            => true,
    'rewrite'               => array( 'slug' => 'custom-post-type' ),
  );
  register_post_type( 'custom_post_type', $args );

}
add_action( 'init', 'plugin_name_custom_post_type' );
```

### Neues Widget:
Im Ordner `src` erstellen Sie die Datei `custom-widget.php` und Fügen Sie Folgendes hinzu:

```php
<?php
/**
 * Register Custom Widget
 */
function plugin_name_custom_widget() {

  class Plugin_Name_Custom_Widget extends WP_Widget {
    /**
     * Register widget with WordPress.
     */
    function __construct() {
      parent::__construct(
        'plugin_name_custom_widget',
        __( 'Custom Widget' ),
        array( 'description' => __( 'A custom widget for your website.' ) )
      );
    }

    /**
     * Front-end display of widget.
     *
     * @see WP_Widget::widget()
     *
     * @param array $args     Widget arguments.
     * @param array $instance Saved values from database.
     */
    public function widget( $args, $instance ) {

      $title = apply_filters( 'widget_title', $instance['title'] );

      echo $args['before_widget'];

      if ( ! empty( $title ) ) {
        echo $args['before_title'] . esc_html( $title ) . $args['after_title'];
      }

      // Your widget content goes here

      echo $args['after_widget'];

    }

    /**
     * Back-end widget options form.
     *
     * @see WP_Widget::form()
     *
     * @param array $instance Previously saved values from database.
     */
    public function form( $instance ) {
      if ( isset( $instance['title'] ) ) {
        $title = $instance['title'];
      } else {
        $title = __( 'New Title', 'plugin-name' );
      }

      ?>

      <p>
        <label for="<?php echo $this->get_field_id( 'title' ); ?>"><?php _e( 'Title:' ); ?></label>
        <input class="widefat" id="<?php echo $this->get_field_id( 'title' ); ?>" name="<?php echo $this->get_field_name( 'title' ); ?>" type="text" value="<?php echo esc_attr( $title ); ?>">
      </p>

      <?php
    }

    /**
     * Sanitize widget form values as they are saved.
     *
     * @see WP_Widget::update()
     *
     * @param array $new_instance Values just sent to WordPress.
     * @param array $old_instance Previously saved values from database.
     *
     * @return array Updated values to be saved.
     */
    public function update( $new_instance, $old_instance ) {
      $instance = array();
      $instance['title'] = strip_tags( $new_instance['title'] );

      return $instance;
    }
  }

  register_widget( 'Plugin_Name_Custom_Widget' );

}
add_action( 'widgets_init', 'plugin_name_custom_widget' );
```

### Shortcodes:

Im Ordner `src` erstellen Sie die Datei `shortcodes.php` und Fügen Sie Folgendes hinzu:

```php
<?php
/**
 * Register Shortcodes
 */
function plugin_name_shortcodes() {

  add_shortcode( 'custom_shortcode', function() {
    return '<p>Hello, this is a custom shortcode!</p>';
  } );

}
add_action( 'init', 'plugin_name_shortcodes' );
```

6. Testen und Überprüfen:
Testen Sie das Plugin auf Ihrer lokalen WordPress-Installation, um sicherzustellen, dass es korrekt funktioniert, ohne Warnungen oder Fehlermeldung. Wissen Sie, dass Sie den Quellcode und andere Entwicklerhilfen wie Kommentare und Ausgaben hinzufügen sollten, damit Sie Ihren Code besser begreifen und überprüfen können.

7. Aktualisieren und Warten:

Veröffentlichen Sie Ihre neuesten Updates zu GitHub, und aktualisieren Sie die Versionsnummer in Ihrem `plugin-name.php`-Datei:

```php
/**
 * Plugin Name: Plugin Name
 * Version: 1.0.1
 * ...
 */
```

Stellen Sie sicher, dass Sie regelmäßig Ihre Dokumentation und Ihr Quellcode aktualisieren, um eine bessere Wartung und eine leichtere Code-Rückführung zu gewährleisten.

8. Veröffentlichen:
Veröffentlichen Sie Ihr Plugin auf dem Wordpress.org-Repository, um es anderen WordPress-Nutzern und Entwicklern zur Verfügung zu stellen, und legen Sie Ihre Dokumentation dar.

Dieses allgemeine Plugin-Entwicklungs-Paket kann als Grundlage für Ihr eigenes benutzerdefiniertes WordPress-Plugin dienen. Sollten Sie weitere Funktionen benötigen, kann die Erweiterung einfach ebendort (beispielsweise in einer neuen PHP-Datei innerhalb des `src`-Ordners) hinzugefügt werden. Die benötigten Schritte sollten sich bei Ihrem individuellen Entwicklungsprojekt ändern, jedoch sollten diese allgemeinen Schritte eine gute Start-Position bilden.

Um der Ticktick-API eine Aufgabe hinzuzufügen, brauchen Sie eine Anforderung mit folgendem JSON-Format zu erstellen:

```json
{
  "content": "Aufgabe-Name hier",
  "due": {
    "date": "YYYY-MM-DD",
    "timeZone": "Asia/Tokyo"   # optional, fügen Sie hier Ihre eigenen Timezoneinformationen hinzu
  },
  "priority": "normal",
  "projects": [
    {
      "id": "Projects-ID-hier"
    }
  ],
  "recurrence": {
    "type": "daily",
    "everyDays": [
      1, 2, 3, 4, 5    # nur für die Tag-Wiederholung (optional)
    ],
    "until": null      # optional, Anzahl der wiederholten Aufgaben
  },
  "labels": [
    {
      "id": "Labels-ID-hier"
    }
  ]
}
```

Dieses JSON kann über die `requests`-Bibliothek an die Ticktick-Api gesendet werden:

```python
import requests

# API-Authentifizierung
API_TOKEN = "INSERT_YOUR_TICKTICK_API_TOKEN_HERE"
HEADERS = {
    "Authorization": f"Bearer {API_TOKEN}",
    "Content-Type": "application/json"
}

# JSON-Daten mit Aufgabe-Informationen
TASK_DATA = {
    "content": "Aufgabe-Name hier",
    "due": {
        "date": "YYYY-MM-DD",
        "timeZone": "Asia/Tokyo"  # optional, fügen Sie hier Ihre eigenen Timezoneinformationen hinzu
    },
    "priority": "normal",
    "projects": [
        {
            "id": "Projects-IDs-hier"
        }
    ],
    "recurrence": {
        "type": "daily",
        "everyDays": [
            1, 2, 3, 4, 5  # nur für die Tag-Wiederholung (optional)
        ],
        "until": None  # optional, Anzahl der wiederholten Aufgaben
    },
    "labels": [
        {
            "id": "Labels-IDs-hier"
        }
    ]
}

# API-Endpunkt für die Erstellung einer neuen Aufgabe
URL = "https://api.ticktick.com/api/v1/tasks"

# Anforderung mit den JSON-Daten senden
response = requests.post(URL, headers=HEADERS, json=TASK_DATA)

# Antwort-Status-Code überprüfen
if response.status_code != 200:
    print("Fehler beim Hinzufügen der Aufgabe!")
    print(response.text)
else:
    print("Aufgabe hinzugefügt.")
```

