        ```java
        import java.sql.*;
        import java.util.ArrayList;
        import java.util.List;

        public class OracleEbsDbOperations extends OracleDbOperations {
            private static final String INSERT_INVOICE_QUERY = "INSERT INTO ar invoices (invoice_number, customer_name, customer_address, payment_terms, invoice_amount) " +
                    "VALUES (?, ?, ?, ?, ?)";
            private static final String SELECT_INVOICE_QUERY = "SELECT invoice_number, customer_name, customer_address, payment_terms, invoice_amount FROM ar_invoices WHERE invoice_number = ?";

            public OracleEbsDbOperations(String url, String username, String password) throws SQLException {
                super(url, username, password);
            }

            @Override
            public void createInvoices(List<Invoice> invoices) {
                try (PreparedStatement statement = this.connection.prepareStatement(INSERT_INVOICE_QUERY, Statement.RETURN_GENERATED_KEYS)) {
                    for (Invoice invoice : invoices) {
                        statement.setString(1, invoice.getInvoiceNumber());
                        statement.setString(2, invoice.getCustomerName());
                        statement.setString(3, invoice.getCustomerAddress());
                        statement.setString(4, invoice.getPaymentTerms());
                        statement.setDouble(5, invoice.getInvoiceAmount());

                        statement.addBatch();
                    }
                    statement.executeBatch();
                } catch (SQLException e) {
                    e.printStackTrace();
                }
            }

            @Override
            public Invoice executeSelectInvoice(String invoiceNumber, RowMapper<Invoice> rowMapper) throws SQLException {
                try (PreparedStatement statement = this.connection.prepareStatement(SELECT_INVOICE_QUERY)) {
                    statement.setString(1, invoiceNumber);
                    return this.executeSelectQuery(statement, rowMapper);
                }
            }

            <T> T executeSelectQuery(String query, RowMapper<T> rowMapper, Object[] bindParams) throws SQLException {
                try (PreparedStatement statement = this.connection.prepareStatement(query)) {
                    if (bindParams != null) {
                        for (int I = 0; I < bindParams.length; i++) {
                            statement.setObject(i + 1, bindParams[i]);
                        }
                    }

                    try (ResultSet resultSet = statement.executeQuery()) {
                        if (resultSet.next()) {
                            return rowMapper.mapRow(resultSet, 1);
                        }
                    }
                }
                return null;
            }
        }

        public interface RowMapper<T> {
            T mapRow(ResultSet resultSet, int rowNum) throws SQLException;
        }
        ```

