    private final String prefix;

    FlowerCategory(String prefix) {
        this.prefix = prefix.toLowerCase();
    }

    public static FlowerCategory of(String flower) {
        for (FlowerCategory category : values()) {
            if (flower.toUpperCase().startsWith(category.prefix.toUpperCase())) {
                return category;
            }
        }
        // Handeln von nicht übereinstimmenden Blumen
