        self.left_child = None
        self.right_child = None
        self.see_saw = 0


class BST+seeSaw:
    def __init__(self):
        self.root = None

    def insert(self, value):
        if self.root is None:
            self.root = BSTNode(value)
        else:
            self._insert_helper(self.root, value)

    def _insert_helper(self, root, value):
