            else:
                self._insert_helper(root.left_child, value)
        else:
            if root.right_child is None:
                root.right_child = BSTNode(value)
            else:
                self._insert_helper(root.right_child, value)

    def see_saw(self):
        if not self.root:
            return 0
        else:
            return self._see_saw_helper(self.root)

    def _see_saw_helper(self, root):
        if root is None:
            return 0
        else:
            return root.value + self._see_saw_helper(root.left_child) + self._see_saw_helper(root.right_child)
```

