   import Vue from 'vue';
   import { RuleTester } from 'eslint';
   import { Linter } from 'eslint';

   type CheckFunction = (node: Linter.Node) => boolean;

   export default function (context: RuleTester.Rules.Context): RuleTester.Rules__[string] {
     return {
       'vue-lifecycle-hook-status': {
         meta: {
           docs: {
             description:
               'Disallow lifecycle hook methods changing internal component state or calling methods that modify internal component state.',
             category: 'Vue',
             recommended: true,
           },
           schema: [
             {
               type: 'object',
               properties: {
                 checkInternalStateChange: {
                   type: 'boolean',
                   default: true,
                 },
                 checkInnerMethodCall: {
                   type: 'boolean',
                   default: true,
                 },
               },
             },
           ],
         },
         create(context) {
           const { report } = context;

           const checkMethodForInternalStateChange: CheckFunction = (node) => {
             if (
               node.type === 'MethodDefinition' &&
               node.key.name === 'updated' &&
               node.value.expression.callee.object.type === 'ThisExpression'
             ) {
               return report({
                 node,
                 message:
                   "`{name}` method updates internal Vue component state".format({
                     name: node.key.name,
                   }),
                 // Add additional details for debugging purposes
                 data: {
                   messageData: {
                     method: JSON.stringify(node),
                   },
                 },
                 type: 'VueLifecycleHookStatus',
               });
             }

             return false;
           };

           const checkInnerMethodCallForInternalStateChange: CheckFunction = (node) => {
             if (
               node.type === 'CallExpression' &&
               node.callee.object.type === 'ThisExpression' &&
               Vue.prototype[`${node.callee.property.name}`].length >= 2
             ) {
               const [, methodCallParams] = node.arguments;

               const methodCallArgMatchesInternalStateChange = methodCallParams.elements.some((param) => {
                 const { type, value } = param;

                 if (type === 'ObjectExpression') {
                   return Object.keys(value.properties).some((key) =>
                     context.options.checkInternalStateChange && key === 'value'
                   );
                 }

                 if (type === 'Identifier' && (context.options.checkInternalStateChange || key === 'value')) {
                   return true;
                 }

                 return false;
               });

               if (methodCallArgMatchesInternalStateChange) {
                 return report({
                   node,
                   message: 'Calling `{name}` method updates internal Vue component state'.format({
                     name: node.callee.property.name,
                   }),
                   // Add additional details for debugging purposes
                   data: {
                     messageData: {
                       methodCall: JSON.stringify(node),
                     },
                   },
                   type: 'VueLifecycleHookStatus',
                 });
               }

               return false;
             }

             return false;
           };

           return {
             MethodDefinition: checkMethodForInternalStateChange,
             CallExpression: checkInnerMethodCallForInternalStateChange,
           };
         },
       },
     };
   };
   ```

