2. Erstellen einer benutzerdefinierten Regelpolitik für die Überprüfung der Lifecycle-Hook-Methoden, wie folgt:

```js
module.exports = {
  plugins: ['vue'],
  rules: {
    'my-rule/lifecycle-hooks': 'error',
  },
  configs: {
    myRuleConfig: {
      plugins: ['vue'],
      rules: {
        'my-rule/lifecycle-hooks': {
          meta: {
            docs: {
              url: 'https://example.com/my-rule-docs',
            },
            fixable: 'code',
          },
          create: contexts => {
            const forbiddenLifecycleHooks = ['created', 'beforeMount', 'mounted', 'beforeUpdate', 'updated', 'activated', 'deactivated'];

            return contexts.filter(context => {
              // filter only lifecycle hook functions
              return context.node.type === 'FunctionDeclaration' && context.node.method.type === 'MethodDefinition' && context.parent.type === 'ObjectMethod' && forbiddenLifecycleHooks.includes(context.node.method.key.name);
            });
          },
          async report(context) {
            const { node, message } = context;

            // Check if the function calls another lifecycle hook method that modifies internal component state
            const calls = node.body.body.filter(bodyNode => bodyNode.type === 'CallExpression');
            const violation = calls.find(callNode => {
              const calledNode = callNode.arguments[0];
              return calledNode && calledNode.type === 'Identifier' && forbiddenLifecycleHooks.includes(calledNode.name);
            });

            if (violation) {
              context.report({
                node,
                message: `Lifecycle hook ${node.method.key.name} modifies internal component state by calling ${violation.arguments[0].name}.`,
              });
            }
          },
        },
      },
    },
  },
};
```

